        ...props,
        menuDensity: props.menuDensity ?? 'default',
        onClosePanel: innerOnClosePanel,
        allPagesIsAvailable,
        quickAccessIsAvailable,
        innerVisiblePanel,
        menuItems: innerMenuItems,
        panelItems: innerPanelItems,
        size,
        onItemClick,
        onToggleQuickAccess,
    };
};
