import {Icon} from '@gravity-ui/uikit';

import {Logo} from '../../Logo';
import {useAsideHeaderInnerContext} from '../AsideHeaderContext';
import {getAsideHeaderDecorationHeight, getAsideHeaderDensityConfig} from '../density';
import {AsideHeaderItem} from '../types';
import {b} from '../utils';

import {AsideDivider} from './AsideDivider';
import {CompositeBar} from './CompositeBar';

import headerDividerCollapsedIcon from '../../../../assets/icons/divider-collapsed.svg';

const DEFAULT_SUBHEADER_ITEMS: AsideHeaderItem[] = [];
const HEADER_COMPOSITE_ID = 'gravity-ui/navigation-header-composite-bar';

export const Header = () => {
    const {
        logo,
        onItemClick,
        onClosePanel,
        headerDecoration,
        subheaderItems,
        compact,
        menuDensity,
    } = useAsideHeaderInnerContext();
    const {compactWidth} = getAsideHeaderDensityConfig(menuDensity);

    const onLogoClick = useCallback(
        (event: React.MouseEvent<HTMLElement, MouseEvent>) => {
            onClosePanel?.();
            logo?.onClick?.(event);
        },
        [onClosePanel, logo],
    );

    return (
        <div className={b('header', {['with-decoration']: headerDecoration})}>
            {logo && (
                <Logo
                    {...logo}
                    data-gn-aside-transition-row="logo"
                    className={b('logo', logo.className)}
                    onClick={onLogoClick}
                    compact={compact}
                    buttonClassName={b('logo-button')}
                    iconPlaceClassName={b('logo-icon-place')}
                />
            )}

            <CompositeBar
                compositeId={HEADER_COMPOSITE_ID}
                type="subheader"
                menuItemClassName={b('menu-item')}
                compact={compact}
                items={subheaderItems || DEFAULT_SUBHEADER_ITEMS}
                onItemClick={onItemClick}
            />

            <AsideDivider className={b('header-bottom-divider')} transitionId="header" />
            {headerDecoration && (
                <Icon
                    data={headerDividerCollapsedIcon}
                    className={b('header-divider')}
                    width={compactWidth}
                    height={getAsideHeaderDecorationHeight(menuDensity)}
                />
            )}
        </div>
    );
};
