                    onItemClick={onItemClick}
                    inlineGroupChildren={false}
                    isGroupCollapsed={isGroupCollapsed}
                    onToggleGroupCollapsed={onToggleGroupCollapsed}
                    enableQuickAccessPin={enableQuickAccessPin}
