        if (!showQuickAccessPin) {
            return rowNode;
        }

        return (
            <div
                ref={interactiveRowRef}
                className={b('interactive-row', {'menu-popup': menuPopupRow})}
                onMouseLeave={() => setQuickAccessPinSuppressed(false)}
