    if (typeof itemWrapper === 'function') {
        node = wrapWithQuickAccessPin(itemWrapper(params, makeNode, opts) as React.ReactElement);
        highlightedNode =
            bringForward &&
            (itemWrapper(
                params,
                ({icon: iconEl}) => makeIconNode(iconEl, false),
