    }, [innerVisiblePanel, menuGroups, visibleMenuItems]);
    const suppressedCurrentItemIds = React.useMemo(() => {
        const quickAccessSuppressed =
            quickAccessEnabled && !quickAccessHighlightInMainMenu
                ? quickAccessItems.map((item) => item.id)
