        if (href) {
            tagNode = (
                <a {...rowEventProps} href={href} ref={mergedRowRef}>
                    {rowChildren}
                </a>
            );
        } else if (wrappedByItemWrapper) {
            tagNode = (
                <div
                    {...rowEventProps}
                    role={menuItemAriaProps?.role ?? 'button'}
                    onKeyDown={(event) => {
